<?php require 'koneksi.php'; if(!isset($_SESSION['siswa_id'])){header('Location:siswa_login.php');exit;} $id=(int)$_SESSION['siswa_id']; $data=mysqli_query($koneksi,"SELECT p.tgl_pinjam,d.*,b.judul,b.pengarang,b.cover FROM peminjaman p JOIN detail_peminjaman d ON d.id_peminjaman=p.id_peminjaman JOIN buku b ON b.id_buku=d.id_buku WHERE p.id_anggota=$id ORDER BY p.tgl_pinjam DESC,d.id_detail DESC"); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riwayat Peminjaman</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include 'includes/navbar_public.php';?><div class="page" style="max-width:1100px;margin:auto"><h2>🕒 Riwayat Peminjaman</h2><?php if(isset($_GET['sukses'])):?><div class="alert-success">✅ <?=htmlspecialchars($_GET['sukses'])?></div><?php endif;?><div class="card table-wrap"><table class="data-table"><tr><th>Cover</th><th>Judul / Pengarang</th><th>Tgl Pinjam</th><th>Batas Kembali</th><th>Status Buku</th><th>Denda</th><th>Pesan</th></tr><?php while($d=mysqli_fetch_assoc($data)):$status=$d['status'];$pesan=$status==='Dipinjam'?'Belum dikembalikan':'Sudah dikembalikan';?><tr><td><img class="cover-kecil" src="assets/uploads/buku/<?=htmlspecialchars($d['cover'])?>" onerror="this.src='default.png'"></td><td><b><?=htmlspecialchars($d['judul'])?></b><br><small><?=htmlspecialchars($d['pengarang'])?></small></td><td><?=$d['tgl_pinjam']?></td><td><?=$d['tgl_batas_kembali']?></td><td><?=status_badge($status)?></td><td><?=rupiah($d['denda'])?></td><td><?=$pesan?></td></tr><?php endwhile;?></table></div></div></body></html>
